// EDIT ME: map your CSV's actual column headers to BudgetFlow's expected fields.
// Example assumes headers: Date, CategoryId, Description, Amount, PaymentMethod, Type, Notes
const row = $json;
return {
  json: {
    date: row.Date,
    categoryId: row.CategoryId,
    description: row.Description,
    amount: row.Amount,
    paymentMethod: row.PaymentMethod || "Bank Transfer",
    type: row.Type || "EXPENSE",
    notes: row.Notes || null,
  },
};

const items = $input.all();
const ok = items.filter((i) => i.json.ok).length;
const failed = items.length - ok;
return [{ json: { totalRows: items.length, imported: ok, failed } }];
